import os, re, glob

BASE = "/root/.hermes/workspace/chinahospitalsguide"

# Check news articles SEO tags
news_files = sorted(glob.glob(f"{BASE}/news/*.html"))
news_files = [f for f in news_files if os.path.basename(f) not in ['index.html', 'template-news-article.html']]

issues = []
for fpath in news_files:
    fname = os.path.basename(fpath)
    content = open(fpath, encoding='utf-8').read()

    canonical = bool(re.search(r'<link rel="canonical"', content))
    og_title = bool(re.search(r'<meta property="og:title"', content))
    tw_card = bool(re.search(r'<meta name="twitter:card"', content))
    jsonld = bool(re.search(r'<script type="application/ld\+json"', content))

    if not all([canonical, og_title, tw_card, jsonld]):
        missing = []
        if not canonical: missing.append("canonical")
        if not og_title: missing.append("og:title")
        if not tw_card: missing.append("twitter")
        if not jsonld: missing.append("jsonld")
        issues.append(f"{fname}: {', '.join(missing)}")

if issues:
    print(f"News articles needing SEO tags ({len(issues)}):")
    for i in issues:
        print(f"  {i}")
else:
    print(f"All {len(news_files)} news articles: SEO tags present")
"}

