        'canonical': bool(re.search(r'<link rel="canonical"', content)),
        'og:title': bool(re.search(r'<meta property="og:title"', content)),
        'twitter:card': bool(re.search(r'<meta name="twitter:card"', content)),
        'jsonld': bool(re.search(r'<script type="application/ld\+json"', content)),
    }
    missing = [k for k, v in checks.items() if not v]
    if missing:
        issues.append(f"{fname}: {missing}")

if not issues:
    print(f"ALL {len(course_files)} course chapters: SEO OK")
else:
    print(f"Course issues ({len(issues)}):")
